{
  "packet_id": "H6-T03-3",
  "claim_id": "C003",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C003.component",
    "value": "Unclear responsibility for attaching approvals recorded elsewhere is proposed as a possible contributor to missing attachments.",
    "scope": "A suspected explanatory factor, not an established cause.",
    "provenance": {
      "refs": [
        {
          "source_id": "P003",
          "role": "SUPPORT"
        },
        {
          "source_id": "P002",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P003 explicitly proposes the factor while leaving its presence and contribution unestablished; P002 identifies the documentation gap."
    }
  },
  "signal_basis": {
    "component_id": "C003.signal_basis",
    "value": "Making attachment responsibility explicit is followed by fewer missing attachments across comparable covered orders inspected at consistent intervals, with repetition if volume permits. Recurrence and subsequent improvement under alternating responsibility conditions in safe simulation provide additional, simulation-specific evidence.",
    "scope": "Prospective attachment outcomes and safe fictitious-order simulation; alternative causes remain possible, and simulation does not establish live-effect magnitude.",
    "provenance": {
      "refs": [
        {
          "source_id": "P007",
