          "role": "SUPPORT"
        },
        {
          "source_id": "P029",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans specify the intervention, comparison, observed response, optional simulated reversal, and limits on causal interpretation and simulation transfer."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C003.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported within its tentative bounds; no conditional empirical warrant is required."
    }
  },
  "rationale": "The claim identifies a possible contributor without asserting an established cause. Under the stipulated prerequisites and observed signal, improvement after clarifying responsibility licenses that limited hypothesis. It does not require excluding every alternative explanation.",
  "uncertainty": "The factor's actual causal contribution and its role in individual historical gaps remain unresolved; neither is asserted by this claim.",
  "anomalies": []
}
